package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "simple wrap",
			text:  "hello world foo bar",
			width: 10,
			want:   []string{"hello", "world foo", "bar"},
		},
		{
			name:  "word longer than width",
			text:  "superlong short",
			width: 5,
			want:   []string{"superlong", "short"},
		},
		{
			name:  "runs of whitespace collapse",
			text:  "a   b\tc\n\nd",
			width: 20,
			want:   []string{"a b c d"},
		},
		{
			name:  "empty input",
			text:  "",
			width: 5,
			want:   nil,
		},
		{
			name:  "whitespace-only input",
			text:  "   \t\n  ",
			width: 5,
			want:   nil,
		},
		{
			name:  "zero width",
			text:  "hello",
			width: 0,
			want:   nil,
		},
		{
			name:  "negative width",
			text:  "hello",
			width: -3,
			want:   nil,
		},
		{
			name:  "exact fit",
			text:  "abc def",
			width: 7,
			want:   []string{"abc def"},
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 5,
			want:   []string{"hello"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if !equal(got, tt.want) {
				t.Errorf("got %v, want %v", got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if (a == nil) != (b == nil) {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
